<?php
namespace App\Http\Controllers\Api\Admin;use App\Http\Controllers\Controller;use App\Http\Requests\Admin\FinanceRecordsRequest;use App\Services\Admin\FinanceDocumentsConfigurationService;
class FinanceDocumentsConfigurationController extends Controller{public function __construct(private readonly FinanceDocumentsConfigurationService$s){}private function p($r):array{return['canView'=>true,'canExport'=>$r->user()->hasPermission('analytics.export'),'canMutate'=>false];}public function documents(FinanceRecordsRequest$r):array{return['success'=>true,'data'=>$this->s->documents($r->filters(),$this->p($r))];}public function document(FinanceRecordsRequest$r,string$id):array{$x=$this->s->document($id,$this->p($r));abort_if(!$x,404);return['success'=>true,'data'=>$x];}public function configurations(FinanceRecordsRequest$r):array{return['success'=>true,'data'=>$this->s->configurations($r->filters(),$this->p($r))];}}
